package api

// W-FRIEND-HOSTED B5 S12 (DS-106) — "owner box unchanged": owner mode must
// register exactly the route set origin/dev 6606b84bf had, plus ONLY the new
// owner Friends routes. A friend's manifest/artifact/flat routes must NOT
// appear in the owner's route table (they are friend-mode-only).

import (
	"os"
	"sort"
	"strings"
	"testing"
)

// golden fixture: the full owner-mode route list at origin/dev 6606b84bf,
// one "METHOD /path" per line, sorted. Generated by running the server and
// dumping router.Routes().
const ownerRoutesGoldenFile = "testdata/owner-routes-6606b84bf.txt"

// s12NewOwnerRoutes is the ONLY addition owner mode is allowed to have: the
// Friends page API (B2). Everything else a friend wave adds must be gated to
// friend mode and therefore absent from this list.
var s12NewOwnerRoutes = []string{
	"GET /api/owner/friends",
	"POST /api/owner/friends",
	"POST /api/owner/friends/:name/:action",
}

func readGoldenRoutes(t *testing.T) []string {
	t.Helper()
	b, err := os.ReadFile(ownerRoutesGoldenFile)
	if err != nil {
		t.Fatalf("read golden route fixture: %v", err)
	}
	var out []string
	for _, ln := range strings.Split(string(b), "\n") {
		ln = strings.TrimSpace(ln)
		if ln == "" {
			continue
		}
		out = append(out, ln)
	}
	return out
}

func routeSet(t *testing.T, e *updEnv) []string {
	t.Helper()
	var out []string
	for _, r := range e.s.router.Routes() {
		out = append(out, r.Method+" "+r.Path)
	}
	sort.Strings(out)
	return out
}

func setDiff(a, b []string) []string {
	inB := map[string]bool{}
	for _, s := range b {
		inB[s] = true
	}
	var out []string
	for _, s := range a {
		if !inB[s] {
			out = append(out, s)
		}
	}
	sort.Strings(out)
	return out
}

func TestOwnerModeRouteDiffIsOnlyFriendsRoutes(t *testing.T) {
	e := newUpdEnv(t)

	golden := readGoldenRoutes(t)
	sort.Strings(golden)
	now := routeSet(t, e)

	removed := setDiff(golden, now)
	if len(removed) != 0 {
		t.Errorf("owner mode LOST routes vs 6606b84bf: %v", removed)
	}
	added := setDiff(now, golden)

	want := append([]string(nil), s12NewOwnerRoutes...)
	sort.Strings(want)
	if strings.Join(added, "\n") != strings.Join(want, "\n") {
		t.Errorf("owner-mode route diff is not exactly the new Friends routes:\nadded:\n  %s\nwant:\n  %s",
			strings.Join(added, "\n  "), strings.Join(want, "\n  "))
	}
}
